-- Run only on an isolated LOCAL test database after all migrations. No external accounts.
begin;
create temporary table profile_fixture(id uuid primary key,n integer);
insert into profile_fixture select gen_random_uuid(),n from generate_series(1,5)n;
insert into auth.users(id,email,email_confirmed_at) select id,id::text||'@fixture.invalid',now() from profile_fixture;
insert into auth.sessions(id,user_id) select id,id from profile_fixture;
insert into public.slm_profiles(user_id,full_name) select id,'Given SecretSurname' from profile_fixture;
insert into public.slm_roles(user_id) select id from profile_fixture;
insert into public.slm_account_security(user_id,must_change_password) select id,false from profile_fixture;
insert into public.slm_account_sessions(session_id,user_id,security_version) select id,id,1 from profile_fixture;
insert into public.slm_aliases(user_id,login,login_normalized,phone,technical_email)
select id,'fixture'||n,'fixture'||n,'+4800000000'||n,id::text||'@slm.invalid' from profile_fixture where n=1;
insert into public.slm_player_profiles(user_id,nickname,email_account) select id,'Nick'||n,n<>1 from profile_fixture;
create temporary table profile_groups as select gen_random_uuid()id,n from generate_series(1,2)n;
insert into public.slm_groups(id,name,admin_id) select g.id,'Fixture'||g.n,p.id from profile_groups g join profile_fixture p on p.n=g.n+1;
insert into public.slm_group_members(group_id,user_id) select g.id,p.id from profile_groups g cross join profile_fixture p where p.n in(1,5) or p.n=g.n+1;
create function pg_temp.assert_true(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL %',label;end if;raise notice 'PASS %',label;end$$;
do $$declare u uuid;viewer uuid;outsider uuid;admin uuid;ga uuid;gb uuid;scope jsonb;b jsonb;dto jsonb;mode text; visible_rows integer;
begin
 select id into u from profile_fixture where n=1;select id into viewer from profile_fixture where n=5;select id into outsider from profile_fixture where n=4;select id into admin from profile_fixture where n=2;
 select id into ga from profile_groups where n=1;select id into gb from profile_groups where n=2;
 select jsonb_agg(id::text order by id) into scope from profile_groups;
 b:=jsonb_build_object('nickname','Independent','first_name','Given','full_name','Given SecretSurname','display_as','nickname','group_scope',scope,'request_id',gen_random_uuid());
 perform public.slm_premium_profile_save(u,u,b);
 perform pg_temp.assert_true((select login='fixture1' from public.slm_aliases where user_id=u),'nickname independent of legacy login');
 perform pg_temp.assert_true(slm_private.public_player_name(u)='Independent','persisted public nickname');
 perform public.slm_groups_dispatch(u,u,'consent',jsonb_build_object('group_id',ga,'share_full_name',true,'request_id',gen_random_uuid()));
 perform pg_temp.assert_true((select display_as='nickname' from public.slm_profiles where user_id=u),'A/D sharing alone keeps nickname');
 foreach mode in array array['first_name','full_name'] loop
 update public.slm_group_members set share_full_name=false,share_first_name=false where user_id=u;
 b:=b||jsonb_build_object('display_as',mode,'request_id',gen_random_uuid());
 begin perform public.slm_premium_profile_save(u,u,b);raise exception 'missing_confirmation_was_accepted';exception when others then if sqlerrm<>'consent_required' then raise;end if;end;
 perform pg_temp.assert_true((select display_as='nickname' from public.slm_profiles where user_id=u),'B/C cancel/denial has no partial writes');
 b:=b||jsonb_build_object('accept_disclosure',true);perform public.slm_premium_profile_save(u,u,b);perform public.slm_premium_profile_save(u,u,b);
 perform pg_temp.assert_true(slm_private.public_player_name(u)='Independent','unscoped labels never reveal personal name');
 dto:=slm_private.group_profile(viewer,u,ga);
 perform pg_temp.assert_true(dto->>'display_name'=case when mode='first_name' then 'Given' else 'Given SecretSurname' end,'confirmed three-mode group projection');
 perform pg_temp.assert_true(mode<>'first_name' or dto->>'full_name' is null,'first-name-only does not reveal surname');
 perform pg_temp.assert_true(slm_private.group_profile(outsider,u,ga) is null,'outsider denied');
 perform pg_temp.assert_true(slm_private.group_profile(admin,u,ga)->>'full_name'='Given SecretSurname','B3 administrator exception retained');
 b:=b||jsonb_build_object('display_as','nickname','request_id',gen_random_uuid(),'accept_disclosure',false);perform public.slm_premium_profile_save(u,u,b);
 perform pg_temp.assert_true((select bool_and(case when mode='first_name' then share_first_name else share_full_name end) from public.slm_group_members where user_id=u),'G nickname preserves consents');
 end loop;
 b:=b||jsonb_build_object('display_as','full_name','request_id',gen_random_uuid());perform public.slm_premium_profile_save(u,u,b);
 begin perform public.slm_groups_dispatch(u,u,'consent',jsonb_build_object('group_id',ga,'share_full_name',false,'request_id',gen_random_uuid()));raise exception 'missing_revocation_confirmation';exception when others then if sqlerrm<>'consent_required' then raise;end if;end;
 perform public.slm_groups_dispatch(u,u,'consent',jsonb_build_object('group_id',ga,'share_full_name',false,'confirm_nickname',true,'request_id',gen_random_uuid()));
 perform pg_temp.assert_true((select display_as='nickname' from public.slm_profiles where user_id=u),'E revocation atomically restores nickname');
 perform pg_temp.assert_true((select share_full_name from public.slm_group_members where user_id=u and group_id=gb),'different group retains independent consent');
 b:=b||jsonb_build_object('display_as','first_name','accept_disclosure',true,'request_id',gen_random_uuid());perform public.slm_premium_profile_save(u,u,b);
 dto:=slm_private.group_profile(viewer,u,ga);perform pg_temp.assert_true(dto->>'full_name' is null and dto->>'first_name'='Given','two groups different scopes');
 b:=b||jsonb_build_object('display_as','full_name','accept_disclosure',false,'request_id',gen_random_uuid());
 begin perform public.slm_premium_profile_save(u,u,b);raise exception 'surname_escalation';exception when others then if sqlerrm<>'consent_required' then raise;end if;end;
 perform pg_temp.assert_true(true,'F first to full requires surname consent');
 b:=b||jsonb_build_object('group_scope','[]'::jsonb,'request_id',gen_random_uuid());
 begin perform public.slm_premium_profile_save(u,u,b);raise exception 'stale_scope_accepted';exception when others then if sqlerrm<>'stale_scope' then raise;end if;end;
 perform pg_temp.assert_true(true,'changed membership scope fails closed');
 update public.slm_group_members set share_full_name=false where user_id=u;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',viewer,'session_id',viewer)::text,true);
 set local role authenticated;
 select count(*) into visible_rows from public.slm_profiles where user_id=u;
 reset role;
 perform pg_temp.assert_true(visible_rows=0,'RLS denies raw surname to first-name-only member');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',admin,'session_id',admin)::text,true);
 set local role authenticated;
 select count(*) into visible_rows from public.slm_profiles where user_id=u;
 reset role;
 perform pg_temp.assert_true(visible_rows=1,'RLS retains group administrator access');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',outsider,'session_id',outsider)::text,true);
 set local role authenticated;
 select count(*) into visible_rows from public.slm_profiles where user_id=u;
 reset role;
 perform pg_temp.assert_true(visible_rows=0,'RLS outsider cannot read raw personal data');
 perform pg_temp.assert_true((select security_version=1 from public.slm_account_sessions where session_id=u),'profile edit preserves live session');
 select id into u from profile_fixture where n=2;
 select coalesce(jsonb_agg(group_id::text order by group_id),'[]') into scope from public.slm_group_members where user_id=u;
 b:=jsonb_build_object('nickname','Email nickname','first_name','','full_name','Email Secret','display_as','first_name','group_scope',scope,'accept_disclosure',true,'request_id',gen_random_uuid());perform public.slm_premium_profile_save(u,u,b);
 perform pg_temp.assert_true(slm_private.profile_display_name(u,u,null)='Email nickname','email account and missing first-name fallback');
 perform pg_temp.assert_true(not has_function_privilege('authenticated','public.slm_premium_profile_save(uuid,uuid,jsonb)','execute'),'client cannot call privileged RPC');
end $$;
rollback;
